__NUXT_JSONP__("/desarrollo-sostenible/eventos/dialogan_sobre_buenas_practicas_en_gestion_municipal_especialistas_y_autoridades_de_san_pedro_garza_garcia_nuevo_leon", (function(a,b,c,d,e){return {data:[{post:{slug:"dialogan_sobre_buenas_practicas_en_gestion_municipal_especialistas_y_autoridades_de_san_pedro_garza_garcia_nuevo_leon",title:"Dialogan sobre buenas prácticas en gestión municipal  especialistas y autoridades de San Pedro Garza García, Nuevo León",date:"2024-02-07T21:49:39.375Z",img:"https:\u002F\u002Fucarecdn.com\u002F25bd302e-fd32-4b4c-b214-29939ab72bce\u002F","img-alt":"San Pedro Garza García",autor:"Ethos",category:"desarrollo-sostenible",extracto:"La directora de Ethos, Liliana Alvarado, formó parte de un equipo multidisciplinario que visitó este municipio neoleonés.",galeria:["https:\u002F\u002Fucarecdn.com\u002F204b4710-f274-45d0-974a-00140e2c3b28\u002F","https:\u002F\u002Fucarecdn.com\u002Ff7ce92cd-b999-436f-98db-8eef38432b56\u002F","https:\u002F\u002Fucarecdn.com\u002F2c355534-e0f9-4e73-97f0-d1a4266c19c7\u002F"],toc:[],body:{type:"root",children:[{type:b,tag:c,props:{},children:[{type:a,value:"Liliana Alvarado, directora general de Ethos, fue parte de un grupo multidisciplinario de especialistas que visitó el municipio de San Pedro Garza García, Nuevo León, para conocer las estrategias exitosas que han desarrollado en materia de seguridad, gestión urbana y sistema de cuidados."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"En compañía del alcalde Miguel B. Treviño de Hoyos, la presidenta del Sistema Municipal DIF Irene Ovalle y otros funcionarios municipales, recorrieron instalaciones policiales, parques emblemáticos del municipio y un Centro de Atención Infantil, que forma parte del sistema de cuidados municipal."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Durante su estancia en este municipio neoleonés, también se reunió con la titular de la Secretaría de Finanzas y Tesorería municipal Rosa María Hinojosa y su equipo de trabajo para dialogar sobre las mejores prácticas en la recaudación del impuesto predial, un rubro en el que han destacado."}]}]},dir:"\u002Feventos",path:"\u002Feventos\u002Fdialogan_sobre_buenas_practicas_en_gestion_municipal_especialistas_y_autoridades_de_san_pedro_garza_garcia_nuevo_leon",extension:".md",createdAt:e,updatedAt:e}}],fetch:{},mutations:[]}}("text","element","p","\n","2024-10-02T22:32:44.078Z")));